/**
 * @distilled.cloud/acme — ACME (RFC 8555) SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model in
 * `.generated-specs` (converted from the hand-authored RFC 8555 OpenAPI by
 * `scripts/convert.ts`). Everything else in this folder is hand-written: the
 * JWS-signing protocol, credentials (account key + directory + EAB), JOSE
 * helpers, retry and errors.
 *
 * @example
 * ```ts
 * import * as Acme from "@distilled.cloud/acme";
 *
 * const account = yield* Acme.acme.newAccount({
 *   contact: ["mailto:ops@example.com"],
 *   termsOfServiceAgreed: true,
 * });
 * const order = yield* Acme.acme.newOrder({
 *   identifiers: [{ type: "dns", value: "*.example.com" }],
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as Jose from "./jose.ts";
export * as T from "./traits.ts";
export * as Retry from "./retry.ts";
export {
  AcmeProtocol,
  type AcmeOpError,
  type AcmeOpContext,
} from "./protocol.ts";
export * from "./services/index.ts";
